@Override
public <T> Observable<T> observe(final Callable<T> promise) {
  return Observable.create(new OnSubscribe<>(promise, new Action2<T, Subscriber<? super T>>() {
    @Override
    public void call(T thing, Subscriber<? super T> subscriber) {
      subscriber.onNext(thing);
    }
  }));
}

@Override
public <I extends Iterable<T>, T> Observable<T> observeEach(final Callable<I> promise) {
  return Observable.create(new OnSubscribe<>(promise, new Action2<I, Subscriber<? super T>>() {
    @Override
    public void call(I things, Subscriber<? super T> subscriber) {
      for (T thing : things) {
        subscriber.onNext(thing);
      }
    }
  }));
}

private class OnSubscribe<T, S> implements Observable.OnSubscribe<S> {
  private final Callable<T> promise;
  private final Action2<T, Subscriber<? super S>> emitter;

  public OnSubscribe(Callable<T> promise, Action2<T, Subscriber<? super S>> emitter) {
    this.promise = promise;
    this.emitter = emitter;
  }

  @Override
  public void call(final Subscriber<? super S> subscriber) {
    try {
      background.exec(promise)
        .onError(new Action<Throwable>() {
          @Override
          public void execute(Throwable throwable) throws Exception {
            subscriber.onError(throwable);
          }
        })
        .then(new Action<T>() {
          @Override
          public void execute(T thing) throws Exception {
            emitter.call(thing, subscriber);
            subscriber.onCompleted();
          }
        });
    } catch (Exception e) {
      throw ExceptionUtils.uncheck(e);
    }
  }
}

public OnSubscribe(Callable<T> promise, Action2<T, Subscriber<? super S>> emitter) {
  this.promise = promise;
  this.emitter = emitter;
}

package org.ratpackframework.registry.internal;

import org.ratpackframework.registry.Registry;
import org.ratpackframework.util.internal.Factory;

import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class LazyChildRegistry extends HierarchicalRegistrySupport {

  private final Class<?> type;
  private final Factory<?> factory;
  private Object object;
  private Lock lock = new ReentrantLock();

  public <T> LazyChildRegistry(Registry parent, Class<T> type, Factory<? extends T> factory) {
    super(parent);
    this.type = type;
    this.factory = factory;
  }

  @Override
  protected <T> T doMaybeGet(Class<T> requestedType) {
    if (type.isAssignableFrom(requestedType)) {
      return requestedType.cast(getObject());
    } else {
      return null;
    }
  }

  private Object getObject() {
    if (object == null) {
      lock.lock();
      try {
        //noinspection ConstantConditions
        if (object == null) {
          object = factory.create();
        }
      } finally {
        lock.unlock();
      }
    }
    return object;
  }

  @Override
  protected String describe() {
    return "LazyHierarchicalRegistry{" + type.getName() + "}";
  }
}

@Override
protected String describe() {
  return "LazyChildRegistry{" + type.getName() + "}";
}

