/**
 * Convenience method for handling last-modified based HTTP caching.
 *
 * @param lastModified The effective last modified date of the response
 * @param runnable    The response sending action if the response needs to be sent
 */
@NonBlocking
void lastModified(Date lastModified, Runnable runnable);

/**
 * {@inheritDoc}
 * @param date The effective last modified date of the response
 * @param serveAction The callback that sends the response if not modified
 */
@Override
@NonBlocking
public void lastModified(Date date, Runnable serveAction) {
  if (response.isNotModified(date)) {
    response.status(304);
  } else {
    response.getHeaders().set("Last-Modified", dateFormat.format(date));
    serveAction.run();
  }
}

public TokenPathBinder(String path, boolean exact) {
    Validations.noLeadingForwardSlash(path, "token path");

    List<String> namesBuilder = new LinkedList<String>();
    String pattern = Pattern.quote(path);

    Pattern placeholderPattern = Pattern.compile("(:\\w+)");
    Matcher matchResult = placeholderPattern.matcher(path);
    while (matchResult.find()) {
      String name = matchResult.group();
      pattern = pattern.replaceFirst(name, "\\\\E([^/?&#]+)\\\\Q");
      namesBuilder.add(name.substring(1));
    }

    pattern = "(".concat(pattern).concat(")");
    if (exact) {
      regex = Pattern.compile(pattern);
    } else {
      regex = Pattern.compile(pattern.concat("(?:/.*)?"));
    }

    this.tokenNames = namesBuilder;
}

public PathBinding bind(String path, PathBinding parentBinding) {
    if (parentBinding != null) {
      path = parentBinding.getPastBinding();
    }

    Matcher matcher = regex.matcher(path);
    if (matcher.matches()) {
      MatchResult matchResult = matcher.toMatchResult();
      String boundPath = matchResult.group(1);
      Map<String, String> paramsBuilder = new LinkedHashMap<String, String>();
      int i = 2;
      for (String name : tokenNames) {
        paramsBuilder.put(name, matchResult.group(i++));
      }

      return new DefaultPathBinding(path, boundPath, paramsBuilder, parentBinding);
    } else {
      return null;
    }
}

package org.ratpackframework.jackson.internal;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.netty.buffer.ByteBuf;
import org.ratpackframework.api.TypeLiteral;
import org.ratpackframework.handling.Context;
import org.ratpackframework.jackson.Json;
import org.ratpackframework.jackson.JsonRenderer;
import org.ratpackframework.render.ByTypeRenderer;
import org.ratpackframework.util.internal.ByteBufWriteThroughOutputStream;

import javax.inject.Inject;
import java.io.IOException;
import java.io.OutputStream;

public class DefaultJsonRenderer extends ByTypeRenderer<Json<?>> implements JsonRenderer {

  private final ObjectMapper defaultObjectMapper;

  @Inject
  public DefaultJsonRenderer(ObjectMapper defaultObjectMapper) {
    super(new TypeLiteral<Json<?>>() {
    });
    this.defaultObjectMapper = defaultObjectMapper;
  }

  @Override
  public void render(final Context context, final Json<?> object) {
    context.respond(context.getByContent().json(new Runnable() {
      @Override
      public void run() {
        final ByteBuf body = context.getResponse().getBody();
        OutputStream outputStream = new ByteBufWriteThroughOutputStream(body);

        try {
          defaultObjectMapper.writeValue(outputStream, object.getObject());
        } catch (IOException e) {
          context.error(e);
        }

        context.getResponse().send();
      }
    }));
  }

}

