package ratpack.test.exec.internal;

import ratpack.exec.ExecControl;
import ratpack.exec.ExecController;
import ratpack.exec.Promise;
import ratpack.exec.Execution;
import ratpack.func.Action;
import ratpack.func.Function;
import ratpack.test.exec.ExecHarness;
import ratpack.test.exec.ExecResult;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicReference;

public class DefaultExecHarness implements ExecHarness {

  private final ExecController controller;

  public DefaultExecHarness(ExecController controller) {
    this.controller = controller;
  }

  @Override
  public <T> ExecResult<T> yield(final Function<Execution, Promise<T>> func) throws Exception {
    final AtomicReference<ExecResult<T>> reference = new AtomicReference<>();
    final CountDownLatch latch = new CountDownLatch(1);

    controller.getControl().exec()
      .onError(throwable -> {
        reference.set(new ResultBackedExecResult<>(Result.<T>failure(throwable)));
        latch.countDown();
      })
      .start(new Action<Execution>() {
        @Override
        public void execute(Execution execution) throws Exception {
          execution.onCleanup(() -> {
            if (latch.getCount() > 0) {
              reference.set(new CompleteExecResult<>());
              latch.countDown();
            }
          });
          Promise<T> promise = func.apply(execution);

          if (promise == null) {
            succeed(null);
          } else {
            promise.then(this::succeed);
          }
        }

        private void succeed(T t) {
          reference.set(t == null ? null : new ResultBackedExecResult<>(Result.success(t)));
          latch.countDown();
        }
      });
    latch.await();
    return reference.get();
  }

  @Override
  public ExecControl getControl() {
    return controller.getControl();
  }

  @Override
  public void close() {
    controller.close();
  }

}

