package org.ratpackframework.path.internal;

import org.ratpackframework.handling.Exchange;
import org.ratpackframework.handling.Handler;
import org.ratpackframework.path.PathBinder;
import org.ratpackframework.path.PathBinding;

import java.util.List;

import static java.util.Collections.singletonList;

public class PathHandler implements Handler {

  private final PathBinder binding;
  private final List<Handler> handlerChain;

  public PathHandler(PathBinder binding, Handler delegate) {
    this.binding = binding;
    this.handlerChain = singletonList(delegate);
  }

  public void handle(Exchange exchange) {
    PathBinding childBinding = binding.bind(
      exchange.getRequest().getPath(),
      exchange.maybeGet(PathBinding.class)
    );
    if (childBinding != null) {
      exchange.insert(
        exchange.getContext().plus(PathBinding.class, childBinding),
        handlerChain
      );
    } else {
      exchange.next();
    }
  }
}

